local({
  mother <- modal_within(as.numeric(mother_pidp), pidp)
  father <- modal_within(as.numeric(father_pidp), pidp)
  case_when(
    !is.na(mother) ~ paste0("m", sprintf("%.0f", mother)),
    !is.na(father) ~ paste0("f", sprintf("%.0f", father)),
    .default = paste0("p", sprintf("%.0f", as.numeric(pidp)))
  )
})

local({
  scale <- coalesce(
    as.numeric(ieqmoecd_dv),
    1 + 0.5 * pmax(as.numeric(hhsize) - as.numeric(nkids_dv) - 1, 0) + 0.3 * as.numeric(nkids_dv)
  )
  income <- as.numeric(fihhmngrs_dv) / scale
  low <- stats::ave(income, wave, FUN = function(x) stats::quantile(x, 0.4, na.rm = TRUE, names = FALSE))
  high <- stats::ave(income, wave, FUN = function(x) stats::quantile(x, 0.6, na.rm = TRUE, names = FALSE))
  case_when(income <= low ~ "Low", income <= high ~ "Medium", income > high ~ "High", .default = "Unknown")
})

local({
  code <- pmin(as.numeric(mother_hiqual_dv), as.numeric(father_hiqual_dv), na.rm = TRUE)
  labels <- attr(mother_hiqual_dv, "labels")
  coalesce(
    lookup_values(
      names(labels)[match(code, labels)],
      lookup_maternal_education,
      dataset_id = spec$dataset_id,
      target_variable = "maternal_education"
    ),
    "Unknown"
  )
})

local({
  items <- cbind(as.numeric(ps2), as.numeric(ps6), as.numeric(ps19), as.numeric(ps32))
  case_when(rowSums(items > 1, na.rm = TRUE) > 0 ~ TRUE, rowSums(!is.na(items)) > 0 ~ FALSE, .default = NA)
})

local({
  asked <- wave %in% c("a", "c", "e", "g", "j")
  computer <- case_when(
    as.numeric(ypcomp) %in% c(2, 3) ~ 0,
    .default = recode_values(as.numeric(ypcpgs), 1 ~ 0, 2 ~ 0.5, 3 ~ 2, 4 ~ 5, 5 ~ 7)
  )
  console <- case_when(
    as.numeric(ypconsol) == 2 ~ 0,
    .default = recode_values(as.numeric(ypconstm), 1 ~ 0, 2 ~ 0.5, 3 ~ 2, 4 ~ 5, 5 ~ 7)
  )
  if_else(asked, computer + console, NA_real_)
})

local({
  wd <- case_when(
    as.numeric(ypsocweb) == 2 ~ 0,
    .default = recode_values(as.numeric(ypnetcht), 1 ~ 0, 2 ~ 0.5, 3 ~ 2, 4 ~ 5, 5 ~ 7)
  )
  we <- case_when(
    as.numeric(ypsocweb) == 2 ~ 0,
    .default = recode_values(as.numeric(ypnetchtw), 1 ~ 0, 2 ~ 0.5, 3 ~ 2, 4 ~ 5, 5 ~ 7)
  )
  if_else(wave %in% c("l", "m", "n", "o"), (wd * 5 + we * 2) / 7, NA_real_)
})

local({
  worst <- pmax(as.numeric(ypfrpbully), as.numeric(ypfrobully), na.rm = TRUE)
  case_when(worst >= 2 ~ "TRUE", worst == 1 ~ "FALSE", .default = NA_character_)
})

local({
  worst <- pmax(as.numeric(ypfrpbulli), as.numeric(ypfrobulli), na.rm = TRUE)
  case_when(worst >= 2 ~ "TRUE", worst == 1 ~ "FALSE", .default = NA_character_)
})

local({
  inches <- coalesce(as.numeric(yphfi), as.numeric(yphti))
  height <- coalesce(as.numeric(yphtc), as.numeric(yphtf) * 30.48 + inches * 2.54)
  weight <- coalesce(as.numeric(ypwtk), (as.numeric(ypwts) * 14 + as.numeric(ypwtp)) * 0.45359237)
  weight / (height / 100)^2
})

coalesce(
  case_when(
    as.numeric(bwtkn_bh) == 1 ~ (as.numeric(bwtlb_bh) * 16 + as.numeric(bwtoz_bh)) * 28.35,
    as.numeric(bwtkn_bh) == 2 ~ as.numeric(bwtgm_bh)
  ),
  case_when(
    as.numeric(bwt) == 1 ~ (as.numeric(bwtlb) * 16 + as.numeric(bwtoz)) * 28.35,
    as.numeric(bwt) == 2 ~ as.numeric(bwtk) * 1000
  )
)

coalesce(
  case_when(
    as.numeric(bwtxp_bh) == 1 | as.numeric(bwtel_bh) == 2 ~ "FALSE",
    as.numeric(bwtel_bh) == 1 ~ if_else(as.numeric(bwtwk_bh) >= 4, "TRUE", "FALSE")
  ),
  case_when(
    as.numeric(bwtxp) == 1 | as.numeric(bwtel) == 2 ~ "FALSE",
    as.numeric(bwtel) == 1 ~ if_else(as.numeric(bwtwk) >= 4, "TRUE", "FALSE")
  )
)
